const payload = $('Calculate Indicators & Build AI Payload').first().json.payload;

// n8n structured parser usually returns parsed result in $json.output
const aiResult = $json.output ?? $json;

const timestamp = new Date().toISOString().replace('T', ' ').replace(/\.\d{3}Z$/, ' UTC');

function getFngEmoji(fngClass) {
  if (fngClass === "Extreme Fear") return "😱";
  if (fngClass === "Fear") return "😟";
  if (fngClass === "Neutral") return "😐";
  if (fngClass === "Greed") return "🙂";
  return "😄";
}

const buy = (aiResult.buy_confidence * 100).toFixed(1);
const hold = (aiResult.hold_confidence * 100).toFixed(1);
const sell = (aiResult.sell_confidence * 100).toFixed(1);

const maxConf = Math.max(
  aiResult.buy_confidence,
  aiResult.hold_confidence,
  aiResult.sell_confidence
);

let signal = "HOLD";
let signalEmoji = "🟡";

if (maxConf === aiResult.buy_confidence) {
  signal = "BUY";
  signalEmoji = "🟢";
}

if (maxConf === aiResult.sell_confidence) {
  signal = "SELL";
  signalEmoji = "🔴";
}

const fngEmoji = getFngEmoji(payload.crypto_fng_class);

const resultJson = JSON.stringify({
  timestamp,
  source: "binance",
  instrument: payload.instrument,
  price_last_14: payload.price_last_14,
  fear_and_greed: payload.crypto_fng_value + " (" + payload.crypto_fng_class + ")",
  ema_20: payload.ema_20,
  ema_50: payload.ema_50,
  ema_100: payload.ema_100,
  price_vs_ema20_percent: payload.price_vs_ema20_percent,
  price_vs_ema50_percent: payload.price_vs_ema50_percent,
  price_vs_ema100_percent: payload.price_vs_ema100_percent,
  rsi_14_last_7: payload.rsi_14_last_7,
  macd_histogram_12_26_9_last_7: payload.macd_histogram_12_26_9_last_7,
  adx_14: payload.adx_14,
  plus_di_14: payload.positive_di_14,
  minus_di_14: payload.negative_di_14,
  di_delta: payload.di_delta_14,
  signal,
  buy_confidence: aiResult.buy_confidence,
  hold_confidence: aiResult.hold_confidence,
  sell_confidence: aiResult.sell_confidence,
  reasoning: aiResult.reasoning
}, null, 2);

const telegramMessage =
  "📊 AI BTC Daily Insight — " + signalEmoji + " " + signal + "\n" +
  fngEmoji + " Fear & Greed: " + payload.crypto_fng_value + " (" + payload.crypto_fng_class + ")\n" +
  "🟢 Buy: " + buy + "% 🟡 Hold: " + hold + "% 🔴 Sell: " + sell + "%\n\n" +
  "```json\n" +
  resultJson +
  "\n```\n" +
  "⚠️ AI-generated technical analysis. Not financial advice.";

return [
  {
    json: {
      payload,
      aiResult,
      signal,
      telegramMessage
    }
  }
];

const config = $('Set Trading Pair').first().json.config;
const candlesRaw = $('Aggregate Candles Into Array').first().json.candles;
const tickRaw = $('Fetch Latest Market Price').first().json;
const fngRaw = $input.first().json;

// Sort candles oldest -> newest, just to be safe
const df = candlesRaw
  .map(d => ({
    TIMESTAMP: d.time * 1000,
    OPEN: parseFloat(d.open),
    HIGH: parseFloat(d.high),
    LOW: parseFloat(d.low),
    CLOSE: parseFloat(d.close),
    VOLUME: parseFloat(d.volume),
  }))
  .sort((a, b) => a.TIMESTAMP - b.TIMESTAMP);

// Sort Fear & Greed oldest -> newest
const fngDataSorted = fngRaw.data.sort(
  (a, b) => parseInt(a.timestamp) - parseInt(b.timestamp)
);

const latestFng = fngDataSorted[fngDataSorted.length - 1];

const fngData = {
  fngValue: parseInt(latestFng.value),
  fngClass: latestFng.value_classification,
};

// Merge latest tick into last candle
const tickValue = parseFloat(tickRaw.price);
const lastIdx = df.length - 1;

df[lastIdx].CLOSE = tickValue;
if (df[lastIdx].HIGH < tickValue) df[lastIdx].HIGH = tickValue;
if (df[lastIdx].LOW > tickValue) df[lastIdx].LOW = tickValue;

function r4(x) {
  return Math.round(parseFloat(x) * 10000) / 10000;
}

function calculateEMA(closes, span) {
  const alpha = 2 / (span + 1);
  const ema = [];

  closes.forEach((price, i) => {
    if (i === 0) {
      ema.push(price);
    } else {
      ema.push(alpha * price + (1 - alpha) * ema[i - 1]);
    }
  });

  return ema;
}

function calculateRSI(closes, period) {
  const rsi = new Array(closes.length).fill(null);
  let avgGain = 0;
  let avgLoss = 0;
  const alpha = 1 / period;

  for (let i = 1; i < closes.length; i++) {
    const delta = closes[i] - closes[i - 1];
    const gain = delta > 0 ? delta : 0;
    const loss = delta < 0 ? -delta : 0;

    if (i === 1) {
      avgGain = gain;
      avgLoss = loss;
    } else {
      avgGain = alpha * gain + (1 - alpha) * avgGain;
      avgLoss = alpha * loss + (1 - alpha) * avgLoss;
    }

    const rs = avgLoss === 0 ? Infinity : avgGain / avgLoss;
    rsi[i] = 100 - (100 / (1 + rs));
  }

  return rsi;
}

function calculateEMAFromArray(arr, span) {
  const alpha = 2 / (span + 1);
  const ema = [];

  arr.forEach((v, i) => {
    if (i === 0) ema.push(v);
    else ema.push(alpha * v + (1 - alpha) * ema[i - 1]);
  });

  return ema;
}

function calculateMACD(closes, fast, slow, signal) {
  const emaFast = calculateEMA(closes, fast);
  const emaSlow = calculateEMA(closes, slow);
  const macdLine = emaFast.map((v, i) => v - emaSlow[i]);
  const signalLine = calculateEMAFromArray(macdLine, signal);
  const histogram = macdLine.map((v, i) => v - signalLine[i]);

  return { macdLine, signalLine, histogram };
}

function calculateADX(highs, lows, closes, period) {
  const n = closes.length;
  const alpha = 1 / period;

  const plusDM = new Array(n).fill(0);
  const minusDM = new Array(n).fill(0);
  const tr = new Array(n).fill(0);

  for (let i = 1; i < n; i++) {
    const upMove = highs[i] - highs[i - 1];
    const downMove = lows[i - 1] - lows[i];

    plusDM[i] = upMove > downMove && upMove > 0 ? upMove : 0;
    minusDM[i] = downMove > upMove && downMove > 0 ? downMove : 0;

    const tr1 = highs[i] - lows[i];
    const tr2 = Math.abs(highs[i] - closes[i - 1]);
    const tr3 = Math.abs(lows[i] - closes[i - 1]);

    tr[i] = Math.max(tr1, tr2, tr3);
  }

  let atr = tr[1];
  let sPlusDM = plusDM[1];
  let sMinusDM = minusDM[1];

  const atrArr = new Array(n).fill(0);
  const sPlusArr = new Array(n).fill(0);
  const sMinusArr = new Array(n).fill(0);

  atrArr[1] = atr;
  sPlusArr[1] = sPlusDM;
  sMinusArr[1] = sMinusDM;

  for (let i = 2; i < n; i++) {
    atr = alpha * tr[i] + (1 - alpha) * atr;
    sPlusDM = alpha * plusDM[i] + (1 - alpha) * sPlusDM;
    sMinusDM = alpha * minusDM[i] + (1 - alpha) * sMinusDM;

    atrArr[i] = atr;
    sPlusArr[i] = sPlusDM;
    sMinusArr[i] = sMinusDM;
  }

  const plusDI = sPlusArr.map((v, i) =>
    atrArr[i] ? 100 * v / atrArr[i] : 0
  );

  const minusDI = sMinusArr.map((v, i) =>
    atrArr[i] ? 100 * v / atrArr[i] : 0
  );

  let adxVal = 0;
  const adxArr = new Array(n).fill(0);

  for (let i = 1; i < n; i++) {
    const sum = plusDI[i] + minusDI[i];
    const dx = sum
      ? Math.abs(plusDI[i] - minusDI[i]) / sum * 100
      : 0;

    adxVal = alpha * dx + (1 - alpha) * adxVal;
    adxArr[i] = adxVal;
  }

  return { adx: adxArr, plusDI, minusDI };
}

const closes = df.map(d => parseFloat(d.CLOSE));
const highs = df.map(d => parseFloat(d.HIGH));
const lows = df.map(d => parseFloat(d.LOW));

const ema20Arr = calculateEMA(closes, 20);
const ema50Arr = calculateEMA(closes, 50);
const ema100Arr = calculateEMA(closes, 100);
const rsi14Arr = calculateRSI(closes, 14);
const { histogram } = calculateMACD(closes, 12, 26, 9);
const { adx, plusDI, minusDI } = calculateADX(highs, lows, closes, 14);

const last = closes.length - 1;
const lastClose = closes[last];

const ema20Last = ema20Arr[last];
const ema50Last = ema50Arr[last];
const ema100Last = ema100Arr[last];

const payload = {
  source: "binance",
  instrument: config.symbol,
  price_last_14: closes.slice(-14).map(r4),
  ema_20: r4(ema20Last),
  ema_50: r4(ema50Last),
  ema_100: r4(ema100Last),
  price_vs_ema20_percent: r4(((lastClose - ema20Last) / ema20Last) * 100),
  price_vs_ema50_percent: r4(((lastClose - ema50Last) / ema50Last) * 100),
  price_vs_ema100_percent: r4(((lastClose - ema100Last) / ema100Last) * 100),
  rsi_14_last_7: rsi14Arr.slice(-7).map(r4),
  macd_histogram_12_26_9_last_7: histogram.slice(-7).map(r4),
  adx_14: r4(adx[last]),
  positive_di_14: r4(plusDI[last]),
  negative_di_14: r4(minusDI[last]),
  di_delta_14: r4(plusDI[last] - minusDI[last]),
  crypto_fng_value: fngData.fngValue,
  crypto_fng_class: fngData.fngClass,
};

return [
  {
    json: {
      payload,
    },
  },
];
